+import { chromium } from 'playwright';
+import { fileURLToPath, pathToFileURL } from 'node:url';
+import { dirname, resolve } from 'node:path';
+import { mkdir } from 'node:fs/promises';
+
+const here = dirname(fileURLToPath(import.meta.url));
+const root = resolve(here, '../..');
+const output = resolve(root, '.tura/captures');
+await mkdir(output, { recursive: true });
+
+const browser = await chromium.launch({ headless: true });
+const failures = [];
+for (const width of [1440, 768, 390]) {
+  const context = await browser.newContext({ viewport: { width, height: width === 390 ? 844 : 900 } });
+  const page = await context.newPage();
+  page.on('console', message => {
+    if (message.type() === 'error') failures.push(`${width}px console: ${message.text()}`);
+  });
+  page.on('pageerror', error => failures.push(`${width}px page: ${error.message}`));
+  await page.goto(pathToFileURL(resolve(root, 'index.html')).href, { waitUntil: 'load' });
+  await page.waitForFunction(() => document.body.dataset.ready === 'true');
+  await page.screenshot({ path: resolve(output, `paris-${width}.png`), fullPage: true });
+  await page.locator('[data-year="2019"]').click();
+  await page.locator('#trend-toggle').uncheck();
+  await page.locator('#unit-f').click();
+  if ((await page.locator('#selected-year').textContent()) !== '2019') failures.push(`${width}px: event selection failed`);
+  if (!(await page.locator('#selected-mean').textContent()).includes('°F')) failures.push(`${width}px: unit toggle failed`);
+  await page.locator('#method-open').click();
+  if (!(await page.locator('#method-panel').getAttribute('data-open'))) failures.push(`${width}px: method panel failed`);
+  await page.keyboard.press('Escape');
+  await context.close();
+}
+await browser.close();
+if (failures.length) {
+  console.error(failures.join('\n'));
+  process.exit(1);
+}
+console.log('PASS: 3 viewports, WebGL load, event selection, trend toggle, unit toggle, and method panel.');
*** End Patch

